CREATE FUNCTION public.pm_billing_register_issued(_items uuid[],_number text,_date date) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p pm_payment_schedule_items;pr pm_projects;g uuid;project uuid;n integer:=0;lines jsonb:='[]';doc uuid;data jsonb; BEGIN IF cardinality(_items) IS NULL OR cardinality(_items)<1 THEN RAISE EXCEPTION 'Invoice selection required';END IF; FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) ORDER BY id LOOP IF n=0 THEN project:=p.project_id;g:=p.manual_billing_group_id;SELECT * INTO pr FROM pm_projects WHERE id=project;END IF; IF p.project_id<>project OR p.manual_billing_group_id IS DISTINCT FROM g OR p.direction<>'inflow' THEN RAISE EXCEPTION 'Incompatible invoice selection';END IF; data:=public.pm_project_incoming_timing(project); lines:=lines||jsonb_build_array(jsonb_build_object('description',coalesce((SELECT description FROM pm_billing_groups WHERE id=g),p.invoice_description,p.label),'quantity',1,'unit_price_ex_vat',p.amount_value,'vat_rate',p.vat_rate,'project_id',project,'payment_schedule_item_id',p.id,'sort_order',n));n:=n+1;END LOOP; IF n<>cardinality(_items) OR (g IS NOT NULL AND n<>(SELECT count(*) FROM pm_payment_schedule_items WHERE manual_billing_group_id=g)) THEN RAISE EXCEPTION 'Issue every member of the group';END IF; IF NOT public.fin_invoice_queue_access() OR NOT public.pm_payment_finance_access(project) THEN RAISE EXCEPTION 'Finance access required' USING ERRCODE='42501';END IF; doc:=public.fin_register_issued_document(jsonb_build_object('doc_type','client_invoice','registration_origin','manual','document_number',_number,'issue_date',_date,'counterparty_client_id',pr.company_id,'project_id',project),lines); FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) LOOP PERFORM public.fin_mark_incoming_issued(p.id,_number,_date);END LOOP;RETURN doc;END $$;
REVOKE ALL ON FUNCTION public.pm_billing_register_issued(uuid[],text,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_register_issued(uuid[],text,date) TO authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.fin_mark_incoming_issued(uuid,text,date)'::regprocedure) INTO d;d:=replace(d,'AND payment_item_id<>_item) THEN','AND payment_item_id<>_item AND NOT (r.manual_billing_group_id IS NOT NULL AND payment_item_id IN(SELECT id FROM public.pm_payment_schedule_items WHERE manual_billing_group_id=r.manual_billing_group_id))) THEN');EXECUTE d;END $$;